// cspell:ignore nbformat

'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var everyBy = require( '@stdlib/array/base/every-by' );
var format = require( '@stdlib/string/format' );
var validateSemanticDocument = require( '@stdlib/_tools/semantic-document/validate' );
var validateOptions = require( './validate.js' );
var validateNotebook = require( './validate_notebook.js' );
var isSourceOrderError = require( './is_source_order_error.js' );
var hasErrors = require( './has_errors.js' );
var targets = require( './targets.js' );
var traverse = require( './traverse.js' );
var diagnostic = require( './diagnostic.js' );
var canonical = require( './canonical.js' );
var resourceIndex = require( './resource_index.js' );
var flowIndex = require( './flow_index.js' );


// FUNCTIONS //

/**
* Creates root notebook metadata.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} target - target adapter
* @param {string} targetName - adapter name
* @param {Object} flow - flow index
* @returns {Object} notebook metadata
*/
function metadata( doc, target, targetName, flow ) {
	var out = {
		'kernelspec': {
			'display_name': target.kernelspec.displayName,
			'language': target.kernelspec.language,
			'name': target.kernelspec.name
		},
		'language_info': canonical( target.languageInfo ),
		'stdlib': {
			'diagnostics': canonical( doc.diagnostics ),
			'kernel_target': {
				'adapter': targetName,
				'adapter_version': target.adapterVersion,
				'project': 'jupyterlite/javascript-kernel',
				'runtime': target.runtime
			},
			'omissions': [],
			'profile': canonical( doc.profile ),
			'semantic_schema_version': doc.schemaVersion,
			'source': canonical( doc.source )
		}
	};
	if ( doc.titleRef !== null ) {
		out.title = flow[ doc.titleRef ].text;
	}
	return out;
}


// MAIN //

/**
* Converts a semantic document to a Jupyter notebook object.
*
* @param {Object} doc - semantic document
* @param {Object} [options] - options
* @throws {TypeError} first argument must be a semantic document
* @throws {TypeError} must provide valid options
* @throws {Error} first argument must be a valid semantic document
* @returns {Object} Jupyter notebook object
*
* @example
* var md2doc = require( '@stdlib/_tools/semantic-document/from-markdown' );
*
* var doc = md2doc( '# Beep\n\n> Boop!' );
* // returns {...}
*
* var nb = toIPYNB( doc );
* // returns {...}
*/
function toIPYNB( doc, options ) {
	var recoverOrder;
	var notebook;
	var embedded;
	var target;
	var errors;
	var state;
	var flow;
	var opts;
	var err;
	var i;

	if ( !isObject( doc ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a semantic document object. Value: `%s`.', doc ) );
	}
	if ( doc.schemaVersion !== '1.0.0' || !doc.profile || doc.profile.version !== '1.0.0' ) {
		throw new TypeError( 'invalid argument. First argument must be a semantic document object having a supported schema and profile version.' );
	}
	if ( arguments.length > 1 ) {
		opts = validateOptions( options );
	} else {
		opts = validateOptions();
	}
	if ( !validateSemanticDocument( doc ) ) {
		errors = validateSemanticDocument.errors.slice();
		recoverOrder = ( opts.mode === 'permissive' ) && everyBy( errors, isSourceOrderError );
		if ( !recoverOrder ) {
			err = new TypeError( 'invalid argument. First argument must be a semantic document object having a supported schema and reference integrity.' );
			err.errors = errors;
			throw err;
		}
	}
	target = targets[ opts.target ];
	flow = flowIndex( doc.children );
	notebook = {
		'cells': [],
		'metadata': metadata( doc, target, opts.target, flow ),
		'nbformat': 4,
		'nbformat_minor': 5
	};
	if ( opts.mode === 'strict' && hasErrors( doc ) ) {
		err = new Error( 'invalid argument. In `strict` mode, a provided semantic document object must not contain error diagnostics.' );
		err.notebook = notebook;
		throw err;
	}
	state = {
		'definitions': resourceIndex( doc.resources.definitions ),
		'diagnostics': notebook.metadata.stdlib.diagnostics,
		'directives': resourceIndex( doc.resources.directives ),
		'ids': {
			'occupied': Object.create( null )
		},
		'notebook': notebook,
		'omissions': notebook.metadata.stdlib.omissions,
		'options': opts,
		'pending': {
			'containers': [],
			'fragments': [],
			'nodes': []
		},
		'recoverOrder': ( recoverOrder === true ),
		'target': target
	};
	if ( state.recoverOrder ) {
		diagnostic( state, 'warning', 'recovered-source-order', 'Semantic leaves were source-sorted because depth-first flow order was inverted.', null );
	}
	embedded = doc.resources.embeddedCode;
	for ( i = 0; i < embedded.length; i++ ) {
		if ( embedded[ i ].execution.intent === 'candidate' ) {
			diagnostic( state, 'info', 'embedded-code-preserved', 'Nested execution candidate remains embedded in its authored Markdown structure.', embedded[ i ] );
		}
	}
	traverse( doc, state );
	if ( !validateNotebook( notebook ) ) {
		errors = validateNotebook.errors.slice();
		diagnostic( state, 'error', 'invalid-notebook', 'Generated notebook does not satisfy nbformat 4.5.', null, {
			'errors': errors
		});
		err = new Error( 'internal error. Generated notebook failed nbformat 4.5 validation.' );
		err.notebook = notebook;
		err.errors = errors;
		throw err;
	}
	return notebook;
}


// EXPORTS //

module.exports = toIPYNB;
